import { getMenubarCheckState, getMenubarPosition, getMenubarState, menubarStyleKeys } from '../lib/core';
import styles from './menubar.module.scss';
import {
	createMenuFamily,
	type MenuCheckboxItemProps,
	type MenuContentProps,
	type MenuGroupProps,
	type MenuItemProps,
	type MenuLabelProps,
	type MenuPortalProps,
	type MenuRadioGroupProps,
	type MenuRadioItemProps,
	type MenuSeparatorProps,
	type MenuShortcutProps,
	type MenuSubProps,
	type MenuSubTriggerProps,
	type MenuTriggerProps,
	type MenubarMenuProps as InternalMenubarMenuProps,
	type MenubarRootProps,
} from '../dropdown-menu/menu-internals';

const family = createMenuFamily({
	prefix: 'Menubar',
	kind: 'menubar',
	styles,
	keys: menubarStyleKeys,
	state: getMenubarState,
	checkState: getMenubarCheckState,
	position: getMenubarPosition,
});

export interface MenubarProps extends MenubarRootProps {}
export interface MenubarPortalProps extends MenuPortalProps {}
export interface MenubarMenuProps extends InternalMenubarMenuProps {}
export interface MenubarTriggerProps extends MenuTriggerProps {
	disabled?: boolean;
}
export interface MenubarContentProps extends MenuContentProps {}
export interface MenubarGroupProps extends MenuGroupProps {}
export interface MenubarLabelProps extends MenuLabelProps {}
export interface MenubarSeparatorProps extends MenuSeparatorProps {}
export interface MenubarShortcutProps extends MenuShortcutProps {}
export interface MenubarItemProps extends MenuItemProps {}
export interface MenubarCheckboxItemProps extends MenuCheckboxItemProps {}
export interface MenubarRadioGroupProps extends MenuRadioGroupProps {}
export interface MenubarRadioItemProps extends MenuRadioItemProps {}
export interface MenubarSubProps extends MenuSubProps {}
export interface MenubarSubTriggerProps extends MenuSubTriggerProps {}
export interface MenubarSubContentProps extends MenuContentProps {}

export function Menubar(props: MenubarProps) {
	return family.MenubarRoot(props);
}
export function MenubarPortal(props: MenubarPortalProps) {
	return family.MenuPortal(props);
}
export function MenubarMenu(props: MenubarMenuProps) {
	return family.MenubarMenu(props);
}
export function MenubarTrigger(props: MenubarTriggerProps) {
	return family.MenubarTrigger(props);
}
export function MenubarContent(props: MenubarContentProps) {
	return family.Content(props);
}
export function MenubarGroup(props: MenubarGroupProps) {
	return family.Group(props);
}
export function MenubarLabel(props: MenubarLabelProps) {
	return family.Label(props);
}
export function MenubarSeparator(props: MenubarSeparatorProps) {
	return family.Separator(props);
}
export function MenubarShortcut(props: MenubarShortcutProps) {
	return family.Shortcut(props);
}
export function MenubarItem(props: MenubarItemProps) {
	return family.Item(props);
}
export function MenubarCheckboxItem(props: MenubarCheckboxItemProps) {
	return family.CheckboxItem(props);
}
export function MenubarRadioGroup(props: MenubarRadioGroupProps) {
	return family.RadioGroup(props);
}
export function MenubarRadioItem(props: MenubarRadioItemProps) {
	return family.RadioItem(props);
}
export function MenubarSub(props: MenubarSubProps) {
	return family.Sub(props);
}
export function MenubarSubTrigger(props: MenubarSubTriggerProps) {
	return family.SubTrigger(props);
}
export function MenubarSubContent(props: MenubarSubContentProps) {
	return family.SubContent(props);
}

export default Menubar;

@use '../../../styles/variables/colors' as *;

// 根容器（横向菜单栏）
.root {
	display: flex;
	align-items: center;
	gap: $spacing-1;
	border-radius: $radius;
	border: 1px solid $border;
	background-color: $background;
	padding: $spacing-1;
}

// 单个菜单容器
.menu {
	position: relative;
	display: inline-flex;
}

// 触发器按钮
.trigger {
	display: flex;
	align-items: center;
	border-radius: $radius-sm;
	padding: $spacing-1 $spacing-2;
	font-size: $text-sm;
	font-weight: $font-medium;
	color: $foreground;
	outline: none;
	user-select: none;
	cursor: pointer;
	transition:
		background-color $transition-fast,
		color $transition-fast;

	&[data-state='open'],
	&[data-highlighted='true'] {
		background-color: $accent;
		color: $accent-foreground;
	}

	&[data-disabled='true'] {
		pointer-events: none;
		opacity: 0.5;
	}
}

// 弹出内容面板
.content {
	position: fixed;
	z-index: $z-dropdown;
	min-width: 12rem;
	overflow: hidden;
	border-radius: $radius;
	border: 1px solid $border;
	background-color: $popover;
	color: $popover-foreground;
	padding: $spacing-1;
	box-shadow: $shadow-md;
	outline: none;
	transition:
		opacity $transition-fast,
		visibility $transition-fast,
		transform $transition-fast;

	&[data-state='closed'] {
		opacity: 0;
		visibility: hidden;
		pointer-events: none;

		&[data-side='top'] {
			transform: translateY(0.25rem);
		}

		&[data-side='bottom'] {
			transform: translateY(-0.25rem);
		}
	}

	&[data-state='open'] {
		opacity: 1;
		visibility: visible;
		pointer-events: auto;
		transform: translate(0, 0);
	}
}

// 子菜单弹出面板
.subContent {
	position: fixed;
	z-index: $z-dropdown;
	min-width: 8rem;
	overflow: hidden;
	border-radius: $radius-md;
	border: 1px solid $border;
	background-color: $popover;
	color: $popover-foreground;
	padding: $spacing-1;
	box-shadow: $shadow-lg;
	outline: none;
	transition:
		opacity $transition-fast,
		visibility $transition-fast,
		transform $transition-fast;

	&[data-state='closed'] {
		opacity: 0;
		visibility: hidden;
		pointer-events: none;
		transform: translateX(-0.25rem);
	}

	&[data-state='open'] {
		opacity: 1;
		visibility: visible;
		pointer-events: auto;
		transform: translate(0, 0);
	}
}

// 分组容器
.group {
	display: block;
}

// 菜单项
.item {
	position: relative;
	display: flex;
	align-items: center;
	gap: $spacing-2;
	border-radius: $radius-sm;
	padding: $spacing-1_5 $spacing-2;
	font-size: $text-sm;
	line-height: $leading-normal;
	color: $popover-foreground;
	outline: none;
	cursor: default;
	user-select: none;

	&[data-highlighted='true'] {
		background-color: $accent;
		color: $accent-foreground;
	}

	&[data-inset='true'] {
		padding-left: $spacing-8;
	}

	&[data-variant='destructive'] {
		color: $destructive;

		&[data-highlighted='true'] {
			background-color: color-mix(in srgb, $destructive 10%, transparent);
			color: $destructive;
		}
	}

	&[data-disabled='true'] {
		pointer-events: none;
		opacity: 0.5;
	}

	& > svg {
		pointer-events: none;
		flex-shrink: 0;
		width: 1rem;
		height: 1rem;
		color: $muted-foreground;
	}

	&[data-variant='destructive'] > svg {
		color: $destructive;
	}
}

// 复选框菜单项
.checkboxItem {
	position: relative;
	display: flex;
	align-items: center;
	gap: $spacing-2;
	border-radius: $radius-sm;
	padding: $spacing-1_5 $spacing-2 $spacing-1_5 $spacing-8;
	font-size: $text-sm;
	line-height: $leading-normal;
	color: $popover-foreground;
	outline: none;
	cursor: default;
	user-select: none;

	&[data-highlighted='true'] {
		background-color: $accent;
		color: $accent-foreground;
	}

	&[data-disabled='true'] {
		pointer-events: none;
		opacity: 0.5;
	}

	& > svg {
		pointer-events: none;
		flex-shrink: 0;
		width: 1rem;
		height: 1rem;
		color: $muted-foreground;
	}
}

// 单选组容器
.radioGroup {
	display: block;
}

// 单选菜单项
.radioItem {
	position: relative;
	display: flex;
	align-items: center;
	gap: $spacing-2;
	border-radius: $radius-sm;
	padding: $spacing-1_5 $spacing-2 $spacing-1_5 $spacing-8;
	font-size: $text-sm;
	line-height: $leading-normal;
	color: $popover-foreground;
	outline: none;
	cursor: default;
	user-select: none;

	&[data-highlighted='true'] {
		background-color: $accent;
		color: $accent-foreground;
	}

	&[data-disabled='true'] {
		pointer-events: none;
		opacity: 0.5;
	}

	& > svg {
		pointer-events: none;
		flex-shrink: 0;
		width: 1rem;
		height: 1rem;
		color: $muted-foreground;
	}
}

// 勾选/单选指示器（绝对定位在左侧）
.indicator {
	position: absolute;
	left: $spacing-2;
	display: inline-flex;
	width: 0.875rem;
	height: 0.875rem;
	align-items: center;
	justify-content: center;
	color: currentcolor;

	.checkIcon {
		width: 1rem;
		height: 1rem;
	}

	.radioIcon {
		width: 0.5rem;
		height: 0.5rem;
		fill: currentColor;
	}
}

// 标签
.label {
	padding: $spacing-1_5 $spacing-2;
	font-size: $text-sm;
	font-weight: $font-medium;
	color: $foreground;

	&[data-inset='true'] {
		padding-left: $spacing-8;
	}
}

// 分隔线
.separator {
	margin: $spacing-1 (-$spacing-1);
	height: 1px;
	background-color: $border;
}

// 快捷键文本
.shortcut {
	margin-left: auto;
	font-size: $text-xs;
	letter-spacing: 0.1em;
	color: $muted-foreground;
}

// 子菜单触发器
.subTrigger {
	position: relative;
	display: flex;
	align-items: center;
	gap: $spacing-2;
	border-radius: $radius-sm;
	padding: $spacing-1_5 $spacing-2;
	font-size: $text-sm;
	line-height: $leading-normal;
	color: $popover-foreground;
	outline: none;
	cursor: default;
	user-select: none;

	&[data-highlighted='true'],
	&[data-state='open'] {
		background-color: $accent;
		color: $accent-foreground;
	}

	&[data-inset='true'] {
		padding-left: $spacing-8;
	}

	&[data-disabled='true'] {
		pointer-events: none;
		opacity: 0.5;
	}

	& > svg {
		pointer-events: none;
		flex-shrink: 0;
		width: 1rem;
		height: 1rem;
		color: $muted-foreground;
	}
}

// 子菜单箭头
.chevron {
	margin-left: auto;
	width: 1rem;
	height: 1rem;
}

.root {
	border-radius: var(--tile-menubar-radius, $radius);
	border-color: var(--tile-menubar-border, $border);
	background-color: var(--tile-menubar-background, $background);
	padding: var(--tile-menubar-padding, $spacing-1);
	box-shadow: var(--tile-menubar-shadow, none);
}
.trigger {
	border-radius: var(--tile-menu-item-radius, $radius-sm);
	padding: var(--tile-menubar-trigger-padding, $spacing-1 $spacing-2);
	font-size: var(--tile-menu-font-size, $text-sm);
	color: var(--tile-menu-label-foreground, $foreground);
	&[data-state='open'],
	&[data-highlighted='true'] {
		background-color: var(--tile-menubar-active-background, $accent);
		color: var(--tile-menu-highlight-foreground, $accent-foreground);
	}
	&:focus-visible {
		box-shadow: var(--tile-menu-focus-shadow, none);
	}
}
.content,
.subContent {
	border-color: var(--tile-menu-border, $border);
	background-color: var(--tile-menu-background, $popover);
	color: var(--tile-menu-foreground, $popover-foreground);
	padding: var(--tile-menu-padding, $spacing-1);
}
.content {
	min-width: var(--tile-menu-min-width, 12rem);
	border-radius: var(--tile-menu-panel-radius, $radius);
	box-shadow: var(--tile-menu-shadow, $shadow-md);
}
.subContent {
	min-width: var(--tile-menu-min-width, 8rem);
	border-radius: var(--tile-menu-panel-radius, $radius-md);
	box-shadow: var(--tile-menu-shadow, $shadow-lg);
}
.item,
.checkboxItem,
.radioItem,
.subTrigger {
	border-radius: var(--tile-menu-item-radius, $radius-sm);
	font-size: var(--tile-menu-font-size, $text-sm);
	line-height: var(--tile-menu-line-height, $leading-normal);
	color: var(--tile-menu-foreground, $popover-foreground);
	&[data-highlighted='true'] {
		background-color: var(--tile-menu-highlight-background, $accent);
		color: var(--tile-menu-highlight-foreground, $accent-foreground);
	}
	& > svg {
		color: var(--tile-menu-subtle, $muted-foreground);
	}
	&:focus-visible {
		box-shadow: var(--tile-menu-focus-shadow, none);
	}
}
.item,
.subTrigger {
	padding: var(--tile-menu-item-padding, $spacing-1_5 $spacing-2);
}
.checkboxItem,
.radioItem {
	padding: var(--tile-menu-check-padding, $spacing-1_5 $spacing-2 $spacing-1_5 $spacing-8);
}
.subTrigger[data-state='open'] {
	background-color: var(--tile-menu-highlight-background, $accent);
	color: var(--tile-menu-highlight-foreground, $accent-foreground);
}
.item[data-variant='destructive'] {
	color: var(--tile-menu-destructive-foreground, $destructive);
	& > svg {
		color: var(--tile-menu-destructive-foreground, $destructive);
	}
	&[data-highlighted='true'] {
		background-color: var(--tile-menu-destructive-background, color-mix(in srgb, $destructive 10%, transparent));
		color: var(--tile-menu-destructive-foreground, $destructive);
	}
}
.label {
	padding: var(--tile-menu-label-padding, $spacing-1_5 $spacing-2);
	font-size: var(--tile-menu-label-font-size, $text-sm);
	font-weight: var(--tile-menu-label-font-weight, $font-medium);
	color: var(--tile-menu-label-foreground, $foreground);
}
.item[data-inset='true'],
.subTrigger[data-inset='true'],
.label[data-inset='true'] {
	padding-left: $spacing-8;
}
.separator {
	background-color: var(--tile-menu-separator, $border);
}
.shortcut {
	color: var(--tile-menu-subtle, $muted-foreground);
}

@media (prefers-reduced-motion: reduce) {
	.content,
	.subContent {
		transition: none;
	}
}
